from pathlib import Path
import json,hashlib,os
R=Path('/home/yangfp/five');sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,indent=2)+'\n')
def rec(run,base,scope):
 p=R/run;m=json.loads((p/'metrics.json').read_text());t=m['tokens'];return {'stage':'five-align','run':os.path.relpath(p,base),'status':'recorded','scope':scope,'evidence':[os.path.relpath(p/'run.json',base),os.path.relpath(p/'metrics.json',base)],'time':{'wall_seconds':m['time']['wall_seconds'],'tool_cpu_seconds':m['time'].get('cpu_tool_seconds')},'token':{'input':t.get('input_tokens'),'output':t.get('output_tokens'),'total':t.get('total_tokens'),'cached_input':t.get('cached_input_tokens'),'reasoning_output':t.get('reasoning_output_tokens')},'memory':{'tool_peak_rss_bytes':m['memory'].get('peak_process_tree_rss_sampled_bytes')},'event_ids':[e['event_id'] for e in t.get('events',[])]}
for entry,ns in [('gh_update_ref_from_speed_sp','FiveGhSpeed'),('gh_update_ref_from_accel_sp','FiveGhAccel')]:
 c=R/'paparazzi/models'/entry;a=c/'align';b=a/'report';b.mkdir(exist_ok=True);model=a/'model';manifest=json.loads((model/'compcert-manifest.json').read_text());cbc=json.loads((c/'cbmc/handoff.json').read_text());props=json.loads((c/'cbmc/properties.json').read_text())
 for x in cbc['outputs']:assert sha((c/x['path']).resolve())==x['sha256'],x
 for k in ['Source.v','Execution.v','preprocessed.i','proof/Precondition.v','proof/Obligations.v','proof/Proofs.v']:assert sha(R/manifest['files'][k]['path'])==manifest['files'][k]['sha256'],k
 scope=json.loads((c/'cbmc/report/scope.json').read_text());rows=[]
 for i,x in enumerate(props,1):rows.append({'property':x['property'],'status':'mapped/pending-proof','cbmc_status':x['status'],'scope':{'inputs':'Two nonzero control scenarios; arbitrary guarded signed64 positions and arbitrary six frame float bit patterns','location':x['sourceLocation'],'memory':'Full GuidanceHRef64-byte14-field object, readable8-byte struct argument; distinct four-byte memcpy bit-observation locals','bounds':'entry once, loop-free fixed47-step software helper, unwind1','observation':'Exact float/int bit patterns, complete14-field state frame; automatic guards mapped by actual emitted IDs'},'theorem':ns+'CBC.Proof.goal'+str(i).zfill(3),'proposition':ns+'CBCSpec.Spec.Goal'+str(i).zfill(3)})
 write(a/'spec-map.json',{'schema':'five-cbmc-spec-map/1','request_sha256':sha(a/'request.json'),'backend_manifest_sha256':sha(model/'compcert-manifest.json'),'verification_method':'traditional-bounded-model-checking','scope_sha256':sha(c/'cbmc/report/scope.json'),'properties':rows})
 write(b/'costs.json',{'schema':'five-stage-costs/1','records':[rec('_build/guidance-mode-work/'+rid+'/five-align',b,desc) for rid,desc in [('20261106T111701-63325514f0','Shared initial builtin model generation; superseded immutable history.'),('20261106T113934-a748e16daa','Shared v1 software binding model generation; superseded immutable history.'),('20261106T115725-b49cef19f2','Shared final V2 model generation for both entries; count once. Outer commands account export tool CPU; nested export receipts are provenance, not additional cost.')]],'aggregation':'Count shared token event IDs once; no invented per-case split. Closing mapping authoring receipt is referenced in aggregate after completion.'})
 (b/'report.md').write_text('# CompCert execution model and CBMC alignment\n\nBoth frozen C inputs were exported with CompCert3.17 Csyntax/Cexec on x86-64 Linux little endian, binary32 nearest-even. The actual Source.v is generated and unchanged; Execution.v invokes the real Internal entry using a list of machine values and arbitrary CompCert memory. The model domain includes every argument list and memory, including invalid inputs. No CBMC assumption restricts the execution model.\n\nThe manifest pins compiler, actual source, preprocessed input, semantic libraries, target and all generated outputs. The common integer-restoring C math binding is represented by its actual generated function body. No new external sqrt axiom or ideal IEEE sqrt assumption is used. Native-libm equivalence and formal IEEE accuracy are outside this verification scope.\n\nThe complete122-property ledger is mapped by exact emitted ID and actual source location in ../spec-map.json. Canonical questions and independent Rocq proofs live under ../rocq/cbmc_recheck; mapping alone is not a proof. The two scenario CBMC input assumptions remain a property scope, while broad natural-domain safety and functionality are separately proved over the unrestricted model.\n\nGenerated proof/Precondition.v and obligation scaffolding are immutable unproved interfaces, not the final canonical problem specifications. Actual proof questions are in rocq/<problem>/problem/Spec.v. Execution correspondence covers all eight categories and every original Csem state, including errors; the source and animator domain are not narrowed to valid proof inputs.\n\nHistorical model revisions and all measured authoring/tool costs are retained. Shared exports are counted once.\n')
 out=list(cbc['outputs'])
 for role,p in [('manifest',model/'compcert-manifest.json'),('source_model',model/'Source.v'),('execution_model',model/'Execution.v'),('preprocessed_source',model/'preprocessed.i'),('generated_precondition',model/'proof/Precondition.v'),('generated_obligations',model/'proof/Obligations.v'),('generated_proof_scaffold',model/'proof/Proofs.v'),('spec_map',a/'spec-map.json'),('execution_request',a/'request.json'),('report',b/'report.md'),('costs',b/'costs.json')]:
  out=[x for x in out if x['role']!=role];out.append({'role':role,'path':os.path.relpath(p,c),'sha256':sha(p)})
 write(a/'handoff.json',{'schema':'five-stage-handoff/1','case_id':entry,'stage':'five-align','status':'passed','target':manifest['target'],'paths_relative_to':'case','outputs':out,'limitations':['Generated unrestricted execution model; CBMC scenario assumptions are only property scope.','Property mapping is not itself a Rocq proof.','Fixed C math binding scope excludes native-libm/IEEE-accuracy equivalence.'],'next_stage':'five-rocq'})
 print(entry,len(rows),'all transitive current hashes verified')
